const match = (path: string, text: string, n = 1) => JSON.stringify({ type: 'match', data: { path: { text: path }, lines: { text }, line_number: n, submatches: [{ start: 0, end: 1, match: { text: 'x' } }] } }) + '\n'
const emptySummary = JSON.stringify({ type: 'summary', data: { stats: { matches: 0, matched_lines: 0 } } }) + '\n'
const item = (id: string, command: string, output: string, action: any, extra: any = {}) => ({
  type: 'commandExecution', id, command, cwd: '/workspace', source: 'agent', processId: `pty-${id}`, status: 'completed',
  commandActions: [{ command, ...action }], aggregatedOutput: output, exitCode: 0, durationMs: 12, ...extra,
})
const read = (id: string, command = 'cat a.txt', output = 'one\ntwo\n', path = 'a.txt', extra = {}) => item(id, command, output, { type: 'read', name: path, path }, extra)
const list = (id: string, command: string, output = 'a.txt\0b.txt\0', path: string | null = '.', extra = {}) => item(id, command, output, { type: 'listFiles', path }, extra)
const search = (id: string, command: string, output: string, extra = {}, query = 'x', path: string | null = '.') => item(id, command, output, { type: 'search', query, path }, extra)
